@SuppressLint("WrongConstant") @Override public void writeSampleData(int trackIndex, ByteBuffer data, boolean isKeyFrame, long presentationTimeUs) {
  if (!isStarted) {
    isStarted = true;
    try {
      mediaMuxer.start();
    } catch (RuntimeException e) {
      // Handle the exception, e.g., log it or rethrow
      e.printStackTrace();
      return;
    }
  }
  int offset = data.position();
  int size = data.limit() - offset;
  int flags = isKeyFrame ? C.BUFFER_FLAG_KEY_FRAME : 0;
  bufferInfo.set(offset, size, presentationTimeUs, flags);
  try {
    mediaMuxer.writeSampleData(trackIndex, data, bufferInfo);
  } catch (RuntimeException e) {
    // Handle the exception, e.g., log it or rethrow
    e.printStackTrace();
  }
}
